import ctypes
import numpy as np
gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
gslcblas.gsl_vector_complex_set_size.argtypes = [ctypes.c_void_p, ctypes.c_int]
gslcblas.gsl_vector_complex_set_size.restype = None

def numpy_to_gsl_matrix_complex(np_array):
    gsl_matrix_complex = ctypes.c_void_p(gsl.gsl_matrix_complex_alloc(np_array.shape[0], np_array.shape[1]))
    for i in range(np_array.shape[0]):
        for j in range(np_array.shape[1]):
            gsl.gsl_matrix_complex_set(gsl_matrix_complex, i, j, np_array[i, j])
    return gsl_matrix_complex

def gsl_vector_to_numpy(gsl_vector, size):
    np_array = np.empty(size, dtype=np.complex)
    for i in range(size):
        np_array[i] = gsl.gsl_vector_get(gsl_vector, i)
    return np_array

def compute_eigenvalues(A, B):
    try:
        A_gsl = numpy_to_gsl_matrix_complex(A)
        B_gsl = numpy_to_gsl_matrix_complex(B)
        eigenvalues_gsl = gsl.gsl_vector_complex_alloc(A.shape[0])
        gsl.gsl_eigen_genherm(A_gsl, B_gsl, eigenvalues_gsl)
        eigenvalues = gsl_vector_to_numpy(eigenvalues_gsl, A.shape[0])
        gsl.gsl_vector_complex_free(eigenvalues_gsl)
        gsl.gsl_matrix_complex_free(A_gsl)
        gsl.gsl_matrix_complex_free(B_gsl)
        return eigenvalues
    except Exception as e:
        return str(e)

