# Define the GSLFunction class
class GSLFunction:
    def __init__(self, func):
        self.func = func
        self.gsl_func = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(func)

    def __call__(self, x):
        return self.gsl_func(x)

# Define the integrate function
def integrate(func, a, b, epsabs, epsrel):
    func = GSLFunction(func)
    result, error, neval = gsl.integrate.gsl_integration_qng(func, a, b, epsabs, epsrel)
    return result, error, neval

