# Allocate and initialize the input matrix and tau vector
def allocate_matrix(rows, cols, data):
    matrix = libgsl.gsl_matrix_alloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            libgsl.gsl_matrix_set(matrix, i, j, data[i][j])
    return matrix

def allocate_vector(data):
    vector = libgsl.gsl_vector_alloc(len(data))
    for i in range(len(data)):
        libgsl.gsl_vector_set(vector, i, data[i])
    return vector

# Call the function and verify its return value
def hessenberg_decomp(matrix, tau):
    tau_vector = allocate_vector(tau)
    return libgsl.gsl_linalg_hessenberg_decomp(matrix, tau_vector)

# Print the resulting matrix and tau vector
def print_matrix(matrix):
    rows, cols = libgsl.gsl_matrix_size(matrix)
    for i in range(rows):
        for j in range(cols):
            print(libgsl.gsl_matrix_get(matrix, i, j), end=' ')
        print()

