def lq_decomposition(matrix):
    n = len(matrix)
    m = len(matrix[0])
    A = (ctypes.c_double * (n * m))()  # Create an array to hold the matrix
    tau = (ctypes.c_double * n)()  # Create an array to hold the tau vector
    for i in range(n):
        for j in range(m):
