class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix
        self.gsl_matrix = libgslcblas.gsl_matrix_alloc(len(matrix), len(matrix))
        for i in range(len(matrix)):
            for j in range(len(matrix[i])):
                self.gsl_matrix.setitem(i, j, matrix[i][j])

    def __del__(self):
        libgslcblas.gsl_matrix_free(self.gsl_matrix)

    def to_numpy(self):
        return libgslcblas.gsl_matrix_to_numpy(self.gsl_matrix)

def compute_matrix_exponential(matrix, mode):
    if len(matrix) != len(matrix[0]):
        raise ValueError("Input matrix must be square")
    gsl_matrix = GSLMatrix(matrix)
    result_gsl_matrix = libgslcblas.gsl_matrix_alloc(len(matrix), len(matrix))
    status = libgslcblas.gsl_linalg_exponential_ss(gsl_matrix.gsl_matrix, result_gsl_matrix, mode)
    if status != 0:
        raise RuntimeError("Failed to compute matrix exponential")
    result = result_gsl_matrix.to_numpy()
    libgslcblas.gsl_matrix_free(result_gsl_matrix)
    return result

