# Define the wrapper function
def wrapped_func(x):
    return func(x)

# Define the test function
def test_func(x):
    return wrapped_func(x)

# Create a GSLFunction object
class GSLFunction:
    def __init__(self, func):
        self.func = func

    def __call__(self, x):
        return test_func(x)

# Define the function to find the minimum
def find_minimum(func, x_minimum, x_lower, x_upper):
    func_gsl = GSLFunction(func)
    result = gsl.find_minimum(ctypes.byref(func_gsl), x_minimum, x_lower, x_upper)
    return result

